use std::any::Any;
use std::collections::HashMap;

#[derive(Default)]
struct Document(HashMap<String, Box<dyn Any>>);

impl Document {
    fn put<T: Any>(&mut self, k: &str, v: T) { self.0.insert(k.into(), Box::new(v)); }
    fn get<T: Any>(&self, k: &str) -> Option<&T> { self.0.get(k)?.downcast_ref::<T>() }
}
let mut d = Document::default();
d.put("price", 100_i64);
let price: Option<&i64> = d.get("price");   // None if the stored type differs
